package model;
import java.time.LocalDate; import java.util.*;
public class Prescription { private int prescriptionId,patientId,doctorId; private Integer recordId; private LocalDate prescriptionDate; private String instructions; private List<PrescriptionItem> items=new ArrayList<>(); public int getPrescriptionId(){return prescriptionId;} public void setPrescriptionId(int v){prescriptionId=v;} public int getPatientId(){return patientId;} public void setPatientId(int v){patientId=v;} public int getDoctorId(){return doctorId;} public void setDoctorId(int v){doctorId=v;} public Integer getRecordId(){return recordId;} public void setRecordId(Integer v){recordId=v;} public LocalDate getPrescriptionDate(){return prescriptionDate;} public void setPrescriptionDate(LocalDate v){prescriptionDate=v;} public String getInstructions(){return instructions;} public void setInstructions(String v){instructions=v;} public List<PrescriptionItem> getItems(){return items;} public void setItems(List<PrescriptionItem> v){items=v;} }
